import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { MakeService } from '../../services/make-service';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';

export interface make {
  id: number
  name: string
}

@Component({
  selector: 'app-make',
  imports: [CommonModule, ReactiveFormsModule, FormsModule, RouterLink],
  templateUrl: './make.html',
  styleUrl: './make.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class Make {
make: make[] = [];
  searchTerm = '';

  constructor(private service: MakeService, private cd: ChangeDetectorRef) {}

  ngOnInit() {
    this.service.getAllProducts().subscribe({
      next: (data) => {
        this.make = data;
         this.cd.markForCheck();
        console.log("Products from backend:", this.make);
      },
      error: (err) => console.error("Error fetching parties:", err)
    });
  }

  filteredMakes() {
    const term = this.searchTerm.toLowerCase();
    return this.make.filter(r =>
      r.name.toLowerCase().includes(term)
    );
  }
}
